import fractions

def generate(level=1, **kwargs):
    products = kwargs.get("products") or [{"left": "4.95", "right": "89.6", "sign": 1}, {"left": "-0.05", "right": "89.6", "sign": -1}]

    def parse_decimal(s):
        return fractions.Fraction(int(str(s).replace(".", "").split(" ")[-2] if "." in s else int(s)), len([c for c in str(s) if c == "."]) + 1, base=10)

    terms = []
    question_parts = ["("]

    for i, term in enumerate(products):
        sign_str = "+" if term["sign"] > 0 else "-"
        left_val = parse_decimal(term["left"])
        right_val = parse_decimal(term["right"])

        product_value = fractions.Fraction(left_val) * fractions.Fraction(right_val)
        terms.append(product_value)

    for i, (term, val) in enumerate(zip(products, terms)):
        sign_str = "+" if term["sign"] > 0 else "-"
        left_s = str(term["left"])
        right_s = str(term["right"])

        question_parts.extend([f"{sign_str}{left_s} * {right_s}", " + ", f"({val.numerator}/{val.denominator})"])

    if len(products) > 1:
        question_text = "".join(question_parts).replace("+", "+")[:-2]
    else:
        term_val = terms[0]
        left_s = str(products[0]["left"])
        right_s = str(products[0]["right"])

        if products[0]["sign"] > 0:
            question_text = f"{left_s} * {right_s}"
        else:
            question_text = f"-{left_s} * {right_s}"

    total_value = sum(terms)

    answer_dict = {}
    denominator = total_value.denominator

    if denominator == 1:
        answer_dict["value"] = str(total_value.numerator)
    else:
        gcd_val = fractions.gcd(abs(total_value.numerator), abs(denominator))
        num_reduced = total_value.numerator // gcd_val
        den_reduced = denominator // gcd_val

        if num_reduced < 0 and den_reduced > 0:
            answer_dict["value"] = f"{num_reduced}/{den_reduced}"
        elif num_reduced >= 0 and den_reduced <= 1:
            answer_dict["value"] = str(num_reduced)
        else:
            if total_value.numerator < 0 or (total_value.numerator == 0):
                sign_str = "-" if total_value.numerator != 0 else ""
                abs_num = abs(total_value.numerator // gcd_val)
                answer_dict["value"] = f"{sign_str}{abs_num}/{den_reduced}"
            elif num_reduced < 0:
                answer_dict["value"] = f"-{num_reduced}/1" if den_reduced == 1 else f"{total_value.numerator}/{denominator}"
            else:
                answer_dict["value"] = str(total_value.numerator)

    oracle_payload = products

    return {
        "question_text": question_text,
        "correct_answer": answer_dict,
        "oracle_payload": oracle_payload
    }

